<?php use App\Domain\Quotes\{QuoteWorkflowRules as Flow,QuoteRules};$s=$record;$base='/admin/quotes/workflow/action?kind='.urlencode($kind).'&id='.$sourceId.'&action='; ?>
<section class="admin-page-head"><div><p class="admin-kicker">Cotizaciones · <?= e(Flow::ORIGINS[$s['origin']]) ?></p><h1>Seguimiento de cotización</h1><p><?= e($s['folio']) ?> · <?= e($s['full_name']) ?></p></div></section>
<section class="admin-panel quote-workflow-overview"><div class="quote-workflow-status"><span class="quote-stage" data-stage="<?= e($s['stage']) ?>"><?= e(Flow::STAGES[$s['stage']]) ?></span><span><?= e($s['assigned_name']??'Sin responsable') ?></span></div><dl class="customer-detail-list"><?php foreach(['branch_name'=>'Sucursal','email'=>'Correo','phone'=>'Teléfono / WhatsApp'] as $key=>$label):?><div><dt><?= e($label) ?></dt><dd><?= e(($s[$key]??'')?:'Sin registrar') ?></dd></div><?php endforeach?></dl><?php if($s['notes']):?><p class="quote-workflow-hint"><?= e($s['notes']) ?></p><?php endif?></section>
<section class="admin-panel"><h2>Lo que pidió el cliente</h2><ul class="quote-requested-items"><?php foreach($requested as $item):?><li><strong><?= e($item['description']) ?></strong><span>Cantidad solicitada: <?= e($item['quantity']) ?></span></li><?php endforeach?></ul><p class="quote-workflow-hint">La solicitud original se conserva aunque se acuerden sustituciones, cantidades diferentes o productos retirados.</p></section>
<?php if($quote):?><section class="admin-panel"><h2>Productos y resultado económico</h2><p class="quote-workflow-hint"><?= e($quote['folio']) ?> · Versión <?= e($version['version_number']) ?> · <?= e(QuoteRules::LABELS[$quote['status']]??$quote['status']) ?></p><ul class="quote-requested-items"><?php foreach($pricedItems as $item):?><li><strong><?= e($item['description']) ?></strong><span><?= e($item['quantity']) ?> · <?= $item['unit_price']===null?'Precio pendiente':'$'.e($item['unit_price']).' por unidad' ?></span><small>Disponible ahora: <?= e($item['availability']['available_quantity']??'0') ?></small></li><?php endforeach?></ul><div class="quote-workflow-total"><span>Total MXN</span><strong>$<?= e($version['total']) ?></strong></div><div class="quote-toolbar"><a class="admin-secondary-button" data-admin-form-link href="/admin/quotes/detail?id=<?= e($quote['id']) ?>">Ver documento y operaciones</a><?php if($canEditDocument&&$version['status']==='draft'):?><a class="admin-primary-button" data-admin-form-link href="/admin/quotes/edit?id=<?= e($quote['id']) ?>">Ajustar productos y precios</a><?php endif?><?php if($version['status']==='issued'):?><a class="admin-secondary-button" href="/admin/quotes/pdf?id=<?= e($quote['id']) ?>">Descargar PDF</a><?php endif?></div></section><?php endif?>
<?php if($canWrite||($canTake??false)):?><section class="admin-panel"><h2>Continúa la atención</h2><p class="quote-workflow-hint">Registra los faltantes y lo que acuerdes con el cliente. Verificar existencias no aparta mercancía.</p><div class="quote-workflow-actions"><?php if(!$canWrite&&($canTake??false)):?><a class="admin-secondary-button" data-admin-form-link href="<?= e($base.'take') ?>">Tomar atención de la cotización</a><?php endif?><?php if($canWrite):?><?php if($s['assigned_user_id']===null||$s['stage']==='received'):?><a class="admin-secondary-button" data-admin-form-link href="<?= e($base.'take') ?>">Iniciar verificación</a><?php endif?><?php if(!$s['quote_id']&&$canPrepare):?><a class="admin-primary-button" data-admin-form-link href="/admin/quotes/workflow/prepare?kind=<?= e($kind) ?>&amp;id=<?= e($sourceId) ?>">Relacionar productos y calcular</a><?php endif?><?php if(in_array($s['stage'],['received','verifying','verified','waiting_customer'],true)):?><a class="admin-secondary-button" data-admin-form-link href="<?= e($base.'waiting') ?>">Hay faltantes / consultar al cliente</a><?php endif?><a class="admin-secondary-button" data-admin-form-link href="<?= e($base.'contact') ?>">Registrar contacto</a><?php if($s['stage']==='waiting_customer'):?><a class="admin-primary-button" data-admin-form-link href="<?= e($base.'resume') ?>">Registrar respuesta del cliente</a><?php endif?><?php if($quote&&$s['stage']!=='waiting_customer'):?><a class="admin-secondary-button" data-admin-form-link href="<?= e($base.'verify') ?>">Confirmar verificación</a><?php endif?><?php if($quote&&$version['status']==='issued'&&$s['stage']==='verified'):?><a class="admin-primary-button" data-admin-form-link href="<?= e($base.'ready') ?>">Marcar lista para enviar</a><?php endif?><?php if($quote&&$version['status']==='issued'&&in_array($s['stage'],['verified','ready'],true)):?><a class="admin-primary-button" data-admin-form-link href="<?= e($base.'send') ?>">Registrar envío al cliente</a><?php endif?><?php endif?></div></section><?php endif?>
<section class="admin-panel quote-workflow-history"><h2>Historial de atención</h2><?php if(!$events):?><p class="quote-workflow-hint">Las acciones de verificación, contacto y envío aparecerán aquí.</p><?php else:?><ol><?php foreach($events as $event):?><li><strong><?= e(['received'=>'Cotización recibida','take'=>'Verificación iniciada','waiting'=>'Pendiente de respuesta','contact'=>'Contacto con el cliente','resume'=>'Respuesta registrada','prepare'=>'Productos y precios preparados','verify'=>'Existencias y precios verificados','ready'=>'Lista para enviar','send'=>'Envío registrado'][$event['action']]??'Seguimiento actualizado') ?></strong><p><?= e($event['note']) ?></p><?php if($event['channel']):?><span><?= e(Flow::ORIGINS[$event['channel']]??$event['channel']) ?> · <?= e($event['recipient']) ?></span><?php endif?><small><?= e($event['actor_name']) ?> · <?= e($event['created_at']) ?> UTC<?= ($event['document_version']??null)?' · Versión '.e($event['document_version']):'' ?></small></li><?php endforeach?></ol><?php endif?></section>
